# Hurricane Sandy Coastal-Forcing Causal Graph

You are a coastal-hazards analyst building a causal graph for the late-October 2012 Hurricane Sandy flooding along the New York-New Jersey Atlantic coast. The graph must compare coastal water level and wave evidence against rainfall-only, wind-only, exposure-only, and image-led simplifications.

Use only the local CSX-103 event package. Select package-relative evidence for every value, mechanism node, and rejected simplification.

Construct a directed graph in which true physical triggers, supporting context, receptors, and weak substitutes are separated. The graph should include:

- coastal water-level, wave, altered-shoreline, submerged-debris, navigation-hazard, and coastal recovery/mapping signals;
- event precipitation and peak local wind as context checks;
- exposed population as receptor context rather than a physical trigger;
- SAR pre/post availability as an observation constraint, not direct proof of inundation when scenes are absent.

Return only a compact JSON object:

```json
{
  "final_label": "<winning mechanism label>",
  "causal_graph": {
    "nodes": [
      {"id": "<node_id>", "role": "<trigger|context|receptor|observation_constraint|rejected_simplification>", "evidence": "<short evidence label>"}
    ],
    "edges": [
      {"from": "<node_id>", "to": "<node_id>", "relationship": "<directional process link>"}
    ]
  },
  "mechanism_scores": {
    "coastal_water_level_wave": 0,
    "rainfall_only": 0,
    "wind_only": 0,
    "exposure_only": 0,
    "image_led": 0
  },
  "key_values": {
    "event_days": 0,
    "event_precip_mm": 0.0,
    "peak_10m_wind_kmh": 0.0,
    "exposed_population_million": 0.0,
    "sar_pre_post_counts": "0/0"
  },
  "failed_simplification": "<rainfall/wind/exposure/image simplification that fails and why>"
}
```

The final label should identify the dominant coastal-forcing mechanism and the graph should show why rain, local wind, exposure, and imagery cannot replace the coastal water-level and wave pathway.

compute_gt_py:
#!/usr/bin/env python3
"""Compute CSX-103_Q1 ground truth from package-local evidence."""

from __future__ import annotations

from datetime import date
import html
import json
import re
from pathlib import Path
from typing import Any


SCHEMA_VERSION = "1.0"
TASK_ID = "CSX-103_Q1"
EVENT_ID = "CSX-103"
TARGET_FAMILY = "hurricane_sandy_coastal_forcing_causal_graph"
FINAL_LABEL = "coastal_water_level_wave"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_001_Locked_package_evidence_report.html",
    "data/event_reports/event_reports_003_Locked_event_anchor_Hurricane_Sandy_New_York-New_Jersey_coastal_flooding.json",
    "data/physical_hazard/physical_hazard_003_Open-Meteo_historical_weather_point_API.json",
    "data/exposure_impact/exposure_impact_004_WorldPop_GP_100m_population_sum.json",
    "data/remote_sensing/remote_sensing_003_Sentinel-1_GRD_VV_pre_post_change.json",
]

COASTAL_TESTS = {
    "storm_surge": ("storm surge",),
    "waves": ("waves",),
    "altered_shorelines": ("altered shorelines",),
    "submerged_debris": ("submerged debris",),
    "water_depth_navigation": ("water depths", "navigation surveys"),
    "coastal_mapping_recovery": ("mapping", "coastal recovery"),
}

RUBRIC = [
    {
        "name": "Final label",
        "points": 4,
        "description": "Gives coastal_water_level_wave, or an equivalent concise coastal water-level and wave-impact label, as the winning diagnosis.",
        "partial_credit": "Award 2-3 points for naming coastal flooding without the exact ledger winner; award 1 point for a vague Hurricane Sandy coastal-impact label.",
    },
    {
        "name": "Coastal ledger computation",
        "points": 4,
        "description": "Finds all six official report signals and scores coastal_water_level_wave as 6.",
        "partial_credit": "Award 3 points for five correct signals, 2 points for four correct signals, or 1 point for two to three correct coastal signals without the full score.",
    },
    {
        "name": "Weather numeric anchors",
        "points": 3,
        "description": "Reports 45.4 mm event precipitation and 60.6 km/h peak 10 m wind with appropriate units or unit-implied field names.",
        "partial_credit": "Award 2 points for one exact value plus one approximate value; award 1 point for only one correct weather value.",
    },
    {
        "name": "Exposure and SAR tests",
        "points": 3,
        "description": "Reports about 3.878 million exposed people, SAR pre/post counts of 0/0, and assigns image_led a score of 0.",
        "partial_credit": "Award 2 points for both values with the wrong image score; award 1 point for only the exposure value or only the SAR-count test.",
    },
    {
        "name": "Score comparison",
        "points": 3,
        "description": "Uses the ledger scores 6, 1, 1, 1, and 0 to reject rainfall-only, wind-only, exposure-only, and image-led simplifications.",
        "partial_credit": "Award 2 points for the right winner with one simplified score wrong; award 1 point for the right winner without explicit score comparison.",
    },
    {
        "name": "Compact JSON structure",
        "points": 2,
        "description": "Returns the requested compact JSON fields with numeric values in the expected units and no extra long-form briefing.",
        "partial_credit": "Award 1 point for correct content with minor field-name or formatting issues.",
    },
    {
        "name": "No overextension",
        "points": 1,
        "description": "Avoids extra damage, asset-loss, or image-derived inundation assertions beyond the computed ledger.",
        "partial_credit": "No partial credit; remove this point for any major overextension.",
    },
]


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_root() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def read_json(root: Path, rel_path: str) -> Any:
    return json.loads((root / rel_path).read_text(encoding="utf-8-sig"))


def read_text(root: Path, rel_path: str) -> str:
    return (root / rel_path).read_text(encoding="utf-8", errors="replace")


def html_to_text(raw: str) -> str:
    text = re.sub(r"<(script|style).*?</\1>", " ", raw, flags=re.I | re.S)
    text = re.sub(r"<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", html.unescape(text)).strip()


def rounded(value: float, digits: int = 3) -> float:
    return round(float(value), digits)


def inclusive_days(start: str, end: str) -> int:
    return (date.fromisoformat(end) - date.fromisoformat(start)).days + 1


def contains_any(text: str, terms: tuple[str, ...]) -> bool:
    lower = text.lower()
    return any(term.lower() in lower for term in terms)



def main() -> None:
    task_dir = Path(__file__).resolve().parent
    root = package_root()

    event = read_json(root, "metadata/event.json")
    anchor = read_json(
        root,
        "data/event_reports/event_reports_003_Locked_event_anchor_Hurricane_Sandy_New_York-New_Jersey_coastal_flooding.json",
    )
    report_text = html_to_text(read_text(root, "data/event_reports/event_reports_001_Locked_package_evidence_report.html"))
    open_meteo = read_json(root, "data/physical_hazard/physical_hazard_003_Open-Meteo_historical_weather_point_API.json")
    worldpop = read_json(root, "data/exposure_impact/exposure_impact_004_WorldPop_GP_100m_population_sum.json")
    sentinel1 = read_json(root, "data/remote_sensing/remote_sensing_003_Sentinel-1_GRD_VV_pre_post_change.json")

    start_date = anchor["temporal_window"]["start_date"]
    end_date = anchor["temporal_window"]["end_date"]
    event_days = inclusive_days(start_date, end_date)

    hourly = open_meteo["hourly"]
    precip_values = [float(value) for value in hourly["precipitation"] if value is not None]
    wind_values = [float(value) for value in hourly["wind_speed_10m"] if value is not None]
    event_precip_mm = rounded(sum(precip_values), 1)
    peak_wind_kmh = rounded(max(wind_values), 1)
    population = rounded(worldpop["population_sum"]["population"], 3)
    population_million = rounded(population / 1_000_000, 3)
    pre_count = int(sentinel1["counts"]["pre_count"])
    post_count = int(sentinel1["counts"]["post_count"])

    coastal_hits = {name: contains_any(report_text, terms) for name, terms in COASTAL_TESTS.items()}
    coastal_score = sum(1 for present in coastal_hits.values() if present)
    rainfall_score = 1 if event_precip_mm > 0 else 0
    wind_score = 1 if peak_wind_kmh > 0 else 0
    exposure_score = 1 if population > 0 else 0
    image_score = 1 if pre_count > 0 and post_count > 0 else 0

    score_ledger = {
        "coastal_water_level_wave": coastal_score,
        "rainfall_only": rainfall_score,
        "wind_only": wind_score,
        "exposure_only": exposure_score,
        "image_led": image_score,
    }

    causal_graph = {
        "nodes": [
            {"id": "coastal_water_level_wave", "role": "trigger", "evidence": "six coastal report signals"},
            {"id": "rainfall_context", "role": "context", "evidence": f"event_precip_mm={event_precip_mm}"},
            {"id": "local_wind_context", "role": "context", "evidence": f"peak_10m_wind_kmh={peak_wind_kmh}"},
            {
                "id": "population_receptor",
                "role": "receptor",
                "evidence": f"exposed_population_million={population_million}",
            },
            {
                "id": "sar_observation_constraint",
                "role": "observation_constraint",
                "evidence": f"sar_pre_post_counts={pre_count}/{post_count}",
            },
            {
                "id": "rainfall_only",
                "role": "rejected_simplification",
                "evidence": "rain context score 1 versus coastal score 6",
            },
            {
                "id": "wind_only",
                "role": "rejected_simplification",
                "evidence": "wind context score 1 versus coastal score 6",
            },
            {
                "id": "exposure_only",
                "role": "rejected_simplification",
                "evidence": "exposure is receptor context, not physical trigger",
            },
            {
                "id": "image_led",
                "role": "rejected_simplification",
                "evidence": f"SAR pre/post counts are {pre_count}/{post_count}",
            },
        ],
        "edges": [
            {
                "from": "coastal_water_level_wave",
                "to": "population_receptor",
                "relationship": "dominant coastal forcing reaches exposed receptors",
            },
            {
                "from": "rainfall_context",
                "to": "rainfall_only",
                "relationship": "context exists but cannot replace coastal forcing",
            },
            {
                "from": "local_wind_context",
                "to": "wind_only",
                "relationship": "local wind context exists but cannot replace water-level and wave pathway",
            },
            {
                "from": "population_receptor",
                "to": "exposure_only",
                "relationship": "receptor magnitude cannot be the physical trigger",
            },
            {
                "from": "sar_observation_constraint",
                "to": "image_led",
                "relationship": "absent pre/post scenes prevent image-led diagnosis",
            },
        ],
    }

    primary_gt = {
        "final_label": FINAL_LABEL,
        "causal_graph": causal_graph,
        "mechanism_scores": score_ledger,
        "key_values": {
            "event_days": event_days,
            "event_precip_mm": event_precip_mm,
            "peak_10m_wind_kmh": peak_wind_kmh,
            "exposed_population_million": population_million,
            "sar_pre_post_counts": f"{pre_count}/{post_count}",
        },
        "failed_simplification": "Rainfall-only, wind-only, exposure-only, and image-led explanations do not match the six-signal coastal water-level and wave pathway.",
    }

    output = {
        "schema_version": SCHEMA_VERSION,
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "event": {
                "event_name": event["event_name"],
                "hazard_family": event["hazard_family"],
                "location": anchor["spatial_window"]["location_text"],
                "start_date": start_date,
                "end_date": end_date,
                "inclusive_days": event_days,
            },
            "coastal_tests": coastal_hits,
            "causal_graph": causal_graph,
            "numeric_inputs": {
                "event_precip_mm": event_precip_mm,
                "peak_10m_wind_kmh": peak_wind_kmh,
                "population": population,
                "population_million": population_million,
                "sar_pre_count": pre_count,
                "sar_post_count": post_count,
            },
            "tolerances": {
                "event_precip_mm": 0.2,
                "peak_10m_wind_kmh": 0.2,
                "population_million": 0.001,
            },
        },
        "rubric": {
            "total_points": 20,
            "criteria": RUBRIC,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "spatial_mask_policy_note": "WorldPop derived population and SAR availability counts are used as package-declared derived statistics or observation constraints; georeferencing metadata is not used to validate event location.",
        },
    }

    if sum(item["points"] for item in RUBRIC) != 20:
        raise ValueError("Rubric points must sum to 20")
    if len(primary_gt) > 8:
        raise ValueError("primary_gt has too many keys")

    (task_dir / "computed_gt.json").write_text(
        json.dumps(output, indent=2, ensure_ascii=False, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
